&reftitle.errors;


 Se option non è un'opzione valida, viene lanciato un
 ValueError.

&reftitle.changelog;







     &Version;
     &Description;





     8.3.0

      assert_options ora è deprecata.




     8.0.0

      Se option non è un'opzione valida,
      ora viene lanciato un ValueError.
      In precedenza veniva restituito &false;.

  &reftitle.examples;



   Esempio di assert_options


<?php
// Questa è la nostra funzione per gestire
// i fallimenti delle asserzioni
function assert_failure($file, $line, $assertion, $message)
{
    echo "L'asserzione $assertion in $file alla riga $line è fallita: $message";
}

// Questa è la nostra funzione di test
function test_assert($parameter)
{
    assert(is_bool($parameter));
}

// Imposta le nostre opzioni di assert
assert_options(ASSERT_ACTIVE,   true);
assert_options(ASSERT_BAIL,     true);
assert_options(ASSERT_WARNING,  false);
assert_options(ASSERT_CALLBACK, 'assert_failure');

// Esegue un'asserzione che fallirà
test_assert(1);

// Questo punto non viene mai raggiunto perché ASSERT_BAIL
// è impostato a true
echo 'Mai raggiunto';
?>
